* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: 'Flame Sans', Arial, sans-serif;
    line-height: 1.6;
    background-color: #F5EBDC;
    padding: 0 24px;
    min-height: 100vh;
    padding-bottom: 200vh;
}

.accordion-container {
    margin-top: 0;
}

.accordion-item {
    scroll-margin-top: 0;
}

/* Header wrapper to hold both open and close links */
.accordion-header-wrapper {
    position: relative;
}

/* Style the header buttons */
.accordion-header-open,
.accordion-header-close {
    display: block;
    padding: 20px 60px 20px 20px;
    text-decoration: none;
    font-size: 18px;
    font-weight: bold;
    transition: background 0.3s;
    cursor: pointer;
    position: relative;
    font-family: 'Flame Bold', Arial, sans-serif;
    font-size: 5rem;
    text-transform: uppercase;
    text-align: center;
    color: inherit;
}

/* Add indicator */
.accordion-header-open::after {
    content: '+';
    position: absolute;
    right: 20px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 2rem;
    font-weight: bold;
}

.accordion-header-close::after {
    content: '−';
    position: absolute;
    right: 20px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 2rem;
    font-weight: bold;
}

/* By default, show the "open" link and hide the "close" link */
.accordion-header-close {
    display: none;
}

/* When section is targeted, hide "open" and show "close" */
.accordion-item:target .accordion-header-open {
    display: none;
}

.accordion-item:target .accordion-header-close {
    display: block;
}

/* Hide content by default */
.accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: none;
}

.accordion-content-inner {
    padding: 40px 20px;
}

/* Show content when section is targeted */
.accordion-item:target .accordion-content {
    max-height: 10000px;
}

/* Style for the dummy close target */
#close {
    position: absolute;
    top: 0;
}

.scroll-to-top {
    position: fixed !important;
    bottom: 30px !important;
    right: 30px !important;
    width: 60px;
    height: 60px;
    background-color: #d62300;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    color: white;
    font-size: 2rem;
    font-weight: bold;
    box-shadow: 0 4px 10px rgba(0,0,0,0.3);
    z-index: 9999 !important;
    transition: background-color 0.3s ease;
}

.scroll-to-top:hover {
    background-color: #502314;
}

